/**
 * Main redirect handler for short links
 * URL: /links/{shortSlug}
 */
app.get("/:shortSlug", async (req, res) => {
  const { shortSlug } = req.params;

  try {
    // 1. Fetch link from Firestore
    const linkRef = db.collection("links").doc(shortSlug);
    const doc = await linkRef.get();

    if (!doc.exists) {
      return res.status(404).send("Link not found.");
    }

    const link = doc.data();

    // 2. Check if link is expired
    const now = admin.firestore.Timestamp.now();
    if (now.seconds >= link.expiresAt.seconds) {
      // Increment expired counter (optional)
      await linkRef.update({
        expiredHits: admin.firestore.FieldValue.increment(1),
      });

      // Redirect to "Offer Closed" page
      return res.redirect(301, "https://yourdomain.com/offer-closed"); // Replace with your actual page
    }

    // 3. Link is still active: increment click count and redirect
    await linkRef.update({
      clicks: admin.firestore.FieldValue.increment(1),
      lastClickedAt: now,
    });

    // Optional: Track basic referrer info
