    if (!linkDoc.exists) return res.status(404).send('Link not found');

    const link = linkDoc.data();
    const now = admin.firestore.Timestamp.now();

    // Check expiration (handles both timestamp and date formats)
    const isExpired = link.expiresAt && 
      (link.expiresAt.seconds 
        ? now.seconds > link.expiresAt.seconds 
        : now.toDate() > new Date(link.expiresAt));

    // Increment click count safely
    await linkDoc.ref.update({
      clicks: admin.firestore.FieldValue.increment(1),
      lastClicked: now
    });

    // Redirect based on expiration status
    if (isExpired) {
      return res.redirect(301, 'https://yourdomain.com/offer-closed');
    } else {
      return res.redirect(302, link.longUrl);
    }
  } catch (error) {
    console.error('Redirect error:', error);
    return res.status(500).send('Link service unavailable');
  }
});

