  const slug = Math.random().toString(36).substring(2, 8);

  // Calculate expiration
  const now = admin.firestore.Timestamp.now();
  const expiresAt = new admin.firestore.Timestamp(
    now.seconds + (expiresInHours * 3600),
    now.nanoseconds
  );

